/**
 * Outgoing webhooks: `issue.unassigned` reaches only the enabled endpoints that asked for it.
 */
import { afterAll, beforeAll, describe, expect, it, vi } from "vitest";

vi.mock("@/lib/id", () => import("../server/_support/doubles/id"));
vi.mock("@/lib/logger", async () => (await import("../server/_support/doubles/misc")).loggerModule);

import { eq } from "drizzle-orm";
import { getDb, webhookDeliveries } from "@/server/db";
import * as issueService from "@/server/services/issue-service";
import * as webhookService from "@/server/services/webhook-service";
import { createTenant, issueInput, useTemporaryDatabase } from "../server/_support/fixtures";
import type { Tenant } from "../server/_support/fixtures";
import type { Unsubscribe } from "@/types/event";

let cleanup: () => void;
let tenant: Tenant;
let detach: Unsubscribe;

beforeAll(async () => {
  cleanup = await useTemporaryDatabase();
  tenant = await createTenant("webhooks", "growth");
  detach = webhookService.registerWebhookListeners();
});

afterAll(() => {
  detach();
  cleanup();
});

describe("services/webhook-service", () => {
  it("delivers issue.unassigned once, as the serialised payload, to subscribed enabled endpoints only", async () => {
    const subscribed = await webhookService.createWebhook(tenant.actors.owner, {
      orgId: tenant.org.id,
      url: "https://hooks.example.test/unassigned",
      eventTypes: ["issue.unassigned"],
    });
    const unrelated = await webhookService.createWebhook(tenant.actors.owner, {
      orgId: tenant.org.id,
      url: "https://hooks.example.test/created",
      eventTypes: ["issue.created"],
    });
    const disabled = await webhookService.createWebhook(tenant.actors.owner, {
      orgId: tenant.org.id,
      url: "https://hooks.example.test/disabled",
      eventTypes: ["issue.unassigned"],
    });
    await webhookService.updateWebhook(tenant.actors.owner, {
      orgId: tenant.org.id,
      webhookId: disabled.id,
      enabled: false,
    });

    const issue = await issueService.createIssue(
      tenant.actors.member,
      issueInput(tenant.org.id, tenant.project.id, {
        title: "Webhook me",
        assigneeId: tenant.userIds.admin,
      }),
    );

    await issueService.assignIssue(tenant.actors.member, {
      orgId: tenant.org.id,
      issueId: issue.id,
      assigneeId: null,
    });

    const deliveries = getDb()
      .select()
      .from(webhookDeliveries)
      .where(eq(webhookDeliveries.orgId, tenant.org.id))
      .all();
    const unassignedDeliveries = deliveries.filter(
      (row) => row.eventType === "issue.unassigned",
    );

    expect(unassignedDeliveries).toHaveLength(1);
    expect(unassignedDeliveries[0]?.endpointId).toBe(subscribed.id);
    expect(JSON.parse(unassignedDeliveries[0]?.payload ?? "null")).toMatchObject({
      orgId: tenant.org.id,
      actorId: tenant.userIds.member,
      issueId: issue.id,
      projectId: tenant.project.id,
      previousAssigneeId: tenant.userIds.admin,
    });

    expect(
      deliveries.filter((row) => row.endpointId === unrelated.id && row.eventType === "issue.unassigned"),
    ).toHaveLength(0);
    expect(
      deliveries.filter((row) => row.endpointId === disabled.id),
    ).toHaveLength(0);
  });
});

